import{_ as a,o as e,c as s,ah as l}from"./chunks/framework.ojwJKwrc.js";const k=JSON.parse('{"title":"Heliodor Linux ベンチマーク","description":"","frontmatter":{},"headers":[],"relativePath":"ja/benchmarks/heliodor.md","filePath":"ja/benchmarks/heliodor.md"}'),t={name:"ja/benchmarks/heliodor.md"};function o(r,i,n,h,d,p){return e(),s("div",null,[...i[0]||(i[0]=[l('<h1 id="heliodor-linux-ベンチマーク" tabindex="-1">Heliodor Linux ベンチマーク <a class="header-anchor" href="#heliodor-linux-ベンチマーク" aria-label="Permalink to &quot;Heliodor Linux ベンチマーク&quot;">​</a></h1><p>Heliodor は Celox の大規模な外部 Veryl ワークロードです。固定した Linux イメージを 起動し、同じ設計リビジョンと入力を使って Celox のネイティブバックエンド、tiered JIT、 同期実行の <code>veryl-cc</code> を比較します。tiered ランナーはインタプリタで即座に実行を始め、 バックグラウンドでネイティブコードを生成し、スケジューラの安全点で実行中のシミュレーションを 生成コードへ昇格させます。Cranelift の Linux 起動時間はこの比較の有効な尺度を大幅に 超えるため、計測・公開しません。</p><h2 id="測定するもの" tabindex="-1">測定するもの <a class="header-anchor" href="#測定するもの" aria-label="Permalink to &quot;測定するもの&quot;">​</a></h2><p>次の 2 つを分けて計測します。</p><ol><li>Celox が設計をコンパイルする時間。</li><li>生成されたシミュレータがワークロード全体を実行する時間。</li><li>コンパイルとシミュレーションを並行させる tiered 実行の起動から Linux 完了までの時間。</li></ol><p>生成コードの速度比較に使うのは 2 つ目だけです。途中までの起動、完了時間の推定、 コンパイルだけの結果は、実行成功として扱いません。</p><h2 id="有効な結果" tabindex="-1">有効な結果 <a class="header-anchor" href="#有効な結果" aria-label="Permalink to &quot;有効な結果&quot;">​</a></h2><p>次の条件をすべて満たす実行だけを採用します。</p><ul><li>固定した Heliodor とワークロードのリビジョンを使う。</li><li>設定された Linux 完了マーカーまで到達する。</li><li>コンパイル時間と実行時間を分けて記録する。</li><li>意図した Celox / Veryl リビジョンからランナーをビルドする。</li><li>タイムアウトや意味上の不一致を調査できるログを残す。</li><li>tiered 実行が Linux 完了前に生成コードへ昇格し、生成コードで 1 回以上評価したことを確認する。</li></ul><p>完了マーカーを固定することで、高速に失敗した実行や未完了の起動を性能向上として 誤って報告することを防ぎます。</p><h2 id="ローカル実行" tabindex="-1">ローカル実行 <a class="header-anchor" href="#ローカル実行" aria-label="Permalink to &quot;ローカル実行&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>tiered JIT だけを実行する場合:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">HELIODOR_RUNNERS</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">celox-tiered</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/run-heliodor-bench.sh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span></span></code></pre></div><p>初回は固定した Heliodor checkout の取得にネットワークアクセスが必要です。スクリプトは 使用リビジョン、ビルド構成、完了状態、計測時間を表示します。変更前後の比較には同じ マシンと構成を使ってください。</p><p>公開結果は<a href="./">ベンチマークダッシュボード</a>の <strong>Heliodor Linux</strong> に掲載します。</p>',16)])])}const u=a(t,[["render",o]]);export{k as __pageData,u as default};
